// A single section's enrollment snapshot, as fetched by one run of the
// (simulated) periodic enrollment puller.
export interface SectionSnapshot {
  sectionId: string;
  enrolledCount: number;
  capacity: number;
}

// sectionId -> list of subscriber emails watching that section for an
// open-seat notification.
export type Subscriptions = Record<string, string[]>;

export type NotificationStatus = "sent" | "failed";

export interface NotificationResult {
  sectionId: string;
  to: string;
  status: NotificationStatus;
  error?: string;
}

// Signature intentionally mirrors a real mailer client: async, throws/rejects
// on failure. Implementations should not assume it always resolves.
export type SendEmail = (
  to: string,
  subject: string,
  body: string
) => Promise<void>;
